def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    pillows = image_patch.find("pillow")
    sofas = image_patch.find("sofa")

    if not pillows or not sofas:
        return image_patch

    pillow_sofa_pairs = []
    for pillow in pillows:
        for sofa in sofas:
            if pillow.overlaps_with(sofa.left, sofa.lower, sofa.right, sofa.upper):
                pillow_sofa_pairs.append((pillow, sofa))

    if not pillow_sofa_pairs:
        return image_patch

    best_pair = min(pillow_sofa_pairs, key=lambda pair: abs(pair[0].horizontal_center - pair[1].horizontal_center))
    return best_pair[0]

